import Foundation

/// A base exercise of the library ("Supino Reto"): one per name, as the Exercícios tab, the picker and the
/// exercise screen show them. The equipment, and the grip or variation when there is one, are chosen in the
/// rows of the exercise screen and of the choice sheet; each combination is an exercise of its own
/// (`DefaultExercise`), with its own history, evolution and records.
///
/// Library data only, never stored. The values are those of the approved base list (design/lista-base-dados.json).
struct ExerciseBase: Equatable, Sendable {
    /// The second row: PEGADA or VARIAÇÃO.
    struct SecondRow: Equatable, Sendable {
        enum Kind: Equatable, Sendable {
            /// "PEGADA": Puxada Alta, Barra Fixa, Remada Baixa and Remada.
            case grip
            /// "VARIAÇÃO": the other 24 bases with a second row.
            case variation
        }

        let kind: Kind
        /// The buttons, in their fixed order.
        let options: [String]
        /// The option the row opens on.
        let opensOn: String
    }

    /// The name shown, and the base's identity in the library.
    let name: String
    let group: MuscleGroup
    /// Extra words of the search: popular names and old names ("crossover", "pulley").
    let extraSearch: String
    /// The EQUIPAMENTO row, in its fixed order: the common ones first, then the grey ones, each in the
    /// standard order.
    let equipment: [LibraryEquipment]
    /// The common equipment of this exercise, in the order of the row; the others are shown in grey.
    let common: [LibraryEquipment]
    /// The PEGADA or VARIAÇÃO row; `nil` when the base has none.
    let secondRow: SecondRow?
}

